+import type { AnyColumn } from '~/column.ts';
+import { sql, type SQL, type SQLWrapper } from '../sql.ts';
+
+export type WindowFrameBoundary =
+	| typeof unboundedPreceding
+	| typeof currentRow
+	| typeof unboundedFollowing
+	| ReturnType<typeof preceding>
+	| ReturnType<typeof following>;
+
+type FrameBoundary = { readonly sql: string; readonly order: number };
+
+/** A frame boundary before all rows in the partition. */
+export const unboundedPreceding: FrameBoundary = { sql: 'unbounded preceding', order: -Infinity };
+/** A frame boundary at the current row. */
+export const currentRow: FrameBoundary = { sql: 'current row', order: 0 };
+/** A frame boundary after all rows in the partition. */
+export const unboundedFollowing: FrameBoundary = { sql: 'unbounded following', order: Infinity };
+
+function assertFrameOffset(name: 'preceding' | 'following', value: number): void {
+	if (!Number.isInteger(value) || value < 0) {
+		throw new Error(`${name}() expects a non-negative integer, received ${value}`);
+	}
+}
+
+/** Creates a frame boundary a fixed number of rows or values before the current row. */
+export function preceding(value: number): FrameBoundary {
+	assertFrameOffset('preceding', value);
+	return { sql: `${value} preceding`, order: -value };
+}
+
+/** Creates a frame boundary a fixed number of rows or values after the current row. */
+export function following(value: number): FrameBoundary {
+	assertFrameOffset('following', value);
+	return { sql: `${value} following`, order: value };
+}
+
+export interface WindowFrame {
+	readonly type: 'rows' | 'range';
+	readonly from: WindowFrameBoundary;
+	readonly to: WindowFrameBoundary;
+}
+
+function frame(type: WindowFrame['type'], spec: { from: WindowFrameBoundary; to: WindowFrameBoundary }): WindowFrame {
+	if (spec.from.order > spec.to.order) {
+		throw new Error('Window frame "from" boundary must not be ordered after "to" boundary');
+	}
+	return { type, ...spec };
+}
+
+export function rows(spec: { from: WindowFrameBoundary; to: WindowFrameBoundary }): WindowFrame {
+	return frame('rows', spec);
+}
+
+export function range(spec: { from: WindowFrameBoundary; to: WindowFrameBoundary }): WindowFrame {
+	return frame('range', spec);
+}
+
+export interface WindowSpec {
+	partitionBy?: SQLWrapper | SQLWrapper[];
+	orderBy?: SQLWrapper | SQLWrapper[];
+	frame?: WindowFrame;
+}
+
+export interface WindowDefinition {
+	name: string;
+	spec: WindowSpec;
+}
+
+function asArray<T>(value: T | T[] | undefined): T[] | undefined {
+	return value === undefined ? undefined : Array.isArray(value) ? value : [value];
+}
+
+/** @internal */
+export function buildWindowSpec(spec: WindowSpec): SQL {
+	const partitionBy = asArray(spec.partitionBy);
+	const orderBy = asArray(spec.orderBy);
+	const partitionBySql = partitionBy?.length ? sql`partition by ${sql.join(partitionBy, sql`, `)}` : undefined;
+	const orderBySql = orderBy?.length ? sql`order by ${sql.join(orderBy, sql`, `)}` : undefined;
+	const frameSql = spec.frame
+		? sql`${sql.raw(spec.frame.type)} between ${sql.raw(spec.frame.from.sql)} and ${sql.raw(spec.frame.to.sql)}`
+		: undefined;
+	return sql.join([partitionBySql, orderBySql, frameSql].filter((part): part is SQL => part !== undefined), sql` `);
+}
+
+type WindowValue<T extends SQLWrapper> = T extends AnyColumn ? T['_']['data'] : T extends SQL<infer TValue> ? TValue : unknown;
+
+export class WindowFunctionBuilder<T> {
+	constructor(private readonly expression: SQL<T>) {}
+
+	over(spec: WindowSpec): SQL<T>;
+	over(name: string): SQL<T>;
+	over(specOrName: WindowSpec | string): SQL<T> {
+		return typeof specOrName === 'string'
+			? sql`${this.expression} over ${sql.identifier(specOrName)}`
+			: sql`${this.expression} over (${buildWindowSpec(specOrName)})`;
+	}
+}
+
+function windowFunction<T>(name: string, args: SQLWrapper[] = []): WindowFunctionBuilder<T> {
+	return new WindowFunctionBuilder(sql`${sql.raw(name)}(${sql.join(args, sql`, `)})`);
+}
+
+function positionalArgument(value: number): SQL {
+	return sql.raw(String(value));
+}
+
+function assertPositiveInteger(name: 'ntile' | 'nthValue', value: number): void {
+	if (!Number.isInteger(value) || value <= 0) {
+		throw new Error(`${name}() expects a positive integer, received ${value}`);
+	}
+}
+
+export function rowNumber(): WindowFunctionBuilder<number> { return windowFunction('row_number'); }
+export function rank(): WindowFunctionBuilder<number> { return windowFunction('rank'); }
+export function denseRank(): WindowFunctionBuilder<number> { return windowFunction('dense_rank'); }
+export function ntile(buckets: number): WindowFunctionBuilder<number> {
+	assertPositiveInteger('ntile', buckets);
+	return windowFunction('ntile', [positionalArgument(buckets)]);
+}
+export function percentRank(): WindowFunctionBuilder<number> { return windowFunction('percent_rank'); }
+export function cumeDist(): WindowFunctionBuilder<number> { return windowFunction('cume_dist'); }
+
+export function lag<T extends SQLWrapper>(expression: T): WindowFunctionBuilder<WindowValue<T> | null>;
+export function lag<T extends SQLWrapper>(expression: T, offset: number): WindowFunctionBuilder<WindowValue<T> | null>;
+export function lag<T extends SQLWrapper>(expression: T, offset: number | undefined, defaultValue: unknown): WindowFunctionBuilder<Exclude<WindowValue<T>, null>>;
+export function lag<T extends SQLWrapper>(expression: T, offset?: number, defaultValue?: unknown): WindowFunctionBuilder<WindowValue<T> | null> {
+	const args: SQLWrapper[] = [expression];
+	if (offset !== undefined) args.push(positionalArgument(offset));
+	if (defaultValue !== undefined) args.push(sql`${defaultValue}`);
+	return windowFunction('lag', args);
+}
+
+export function lead<T extends SQLWrapper>(expression: T): WindowFunctionBuilder<WindowValue<T> | null>;
+export function lead<T extends SQLWrapper>(expression: T, offset: number): WindowFunctionBuilder<WindowValue<T> | null>;
+export function lead<T extends SQLWrapper>(expression: T, offset: number | undefined, defaultValue: unknown): WindowFunctionBuilder<Exclude<WindowValue<T>, null>>;
+export function lead<T extends SQLWrapper>(expression: T, offset?: number, defaultValue?: unknown): WindowFunctionBuilder<WindowValue<T> | null> {
+	const args: SQLWrapper[] = [expression];
+	if (offset !== undefined) args.push(positionalArgument(offset));
+	if (defaultValue !== undefined) args.push(sql`${defaultValue}`);
+	return windowFunction('lead', args);
+}
+
+export function firstValue<T extends SQLWrapper>(expression: T): WindowFunctionBuilder<WindowValue<T> | null> { return windowFunction('first_value', [expression]); }
+export function lastValue<T extends SQLWrapper>(expression: T): WindowFunctionBuilder<WindowValue<T> | null> { return windowFunction('last_value', [expression]); }
+export function nthValue<T extends SQLWrapper>(expression: T, n: number): WindowFunctionBuilder<WindowValue<T> | null> {
+	assertPositiveInteger('nthValue', n);
+	return windowFunction('nth_value', [expression, positionalArgument(n)]);
+}
+
+export function windowSum<T extends SQLWrapper>(expression: T): WindowFunctionBuilder<string | null> { return windowFunction('sum', [expression]); }
+export function windowAvg<T extends SQLWrapper>(expression: T): WindowFunctionBuilder<string | null> { return windowFunction('avg', [expression]); }
+export function windowMin<T extends SQLWrapper>(expression: T): WindowFunctionBuilder<WindowValue<T> | null> { return windowFunction('min', [expression]); }
+export function windowMax<T extends SQLWrapper>(expression: T): WindowFunctionBuilder<WindowValue<T> | null> { return windowFunction('max', [expression]); }
+export function windowCount(expression?: SQLWrapper): WindowFunctionBuilder<number> { return windowFunction('count', [expression ?? sql.raw('*')]); }
